/*
 * Placeholder for the vendored Datastar bundle.
 *
 * On first launch this file MUST be replaced with the real Datastar build
 * fetched from https://data-star.dev/ — see ../README.md for the bump procedure.
 *
 * Until then, this stub exposes a no-op signal/action shim so the page renders
 * and the smoke-test button does not error on missing attributes. The shim is
 * NOT a Datastar implementation — it just keeps the scaffold buildable and
 * the index page interactive enough to confirm the wire-up.
 */
(function () {
  if (window.__zimHubDatastarShim) return;
  window.__zimHubDatastarShim = true;

  const log = (...args) => console.info('[zim-hub datastar shim]', ...args);
  log('placeholder loaded — replace static/vendor/datastar.min.js with the real Datastar build');

  function parseSignals(str) {
    try { return Function('"use strict";return (' + str + ')')(); } catch { return {}; }
  }

  function applySignals(root, signals) {
    root.__signals = signals;
    root.querySelectorAll('[data-text]').forEach((el) => {
      const key = el.getAttribute('data-text').replace(/^\$/, '');
      el.textContent = signals[key] ?? '';
    });
  }

  function bind(root) {
    const sigAttr = root.getAttribute('data-signals');
    const signals = sigAttr ? parseSignals(sigAttr) : {};
    applySignals(root, signals);

    root.querySelectorAll('[data-on-click]').forEach((el) => {
      const expr = el.getAttribute('data-on-click');
      el.addEventListener('click', () => {
        try {
          const fn = new Function('signals', 'with (signals) { ' + expr.replace(/\$/g, '') + '; }');
          fn(signals);
          applySignals(root, signals);
        } catch (e) {
          log('expr error', expr, e);
        }
      });
    });
  }

  document.addEventListener('DOMContentLoaded', () => {
    document.querySelectorAll('[data-signals]').forEach(bind);
  });
})();
